cd /tmp && python3 - <<'EOF'
import tempfile
from keyvault_ledger import Vault

v = Vault(tempfile.mkdtemp())
checks = [
    ("empty key id",    ValueError, lambda: v.derive_seal("", b"pw", b"s", 1, 1)),
    ("empty salt",      ValueError, lambda: v.derive_seal("k", b"pw", b"", 1, 1)),
    ("iterations 0",    ValueError, lambda: v.derive_seal("k", b"pw", b"s", 0, 1)),
    ("length -1",       ValueError, lambda: v.derive_seal("k", b"pw", b"s", 1, -1)),
    ("password str",    TypeError,  lambda: v.derive_seal("k", "pw", b"s", 1, 1)),
    ("salt bytearray",  TypeError,  lambda: v.derive_seal("k", b"pw", bytearray(b"s"), 1, 1)),
    ("iterations bool", TypeError,  lambda: v.derive_seal("k", b"pw", b"s", True, 1)),
    ("length float",    TypeError,  lambda: v.derive_seal("k", b"pw", b"s", 1, 1.0)),
]
for label, exc, fn in checks:
    try:
        fn()
        print(f"FAIL {label}: no exception")
    except exc:
        print(f"ok   {label} -> {exc.__name__}")
    except BaseException as e:
        print(f"FAIL {label}: got {type(e).__name__}")

# rejected calls wrote nothing; direct seal gives empty derivation record
assert v.versions("k") == []
v.seal("k", b"m")
assert v.derivation("k") == {}
assert v.manifest()["keys"] == {"k": v.manifest()["keys"]["k"]}
try:
    v.derivation("nope")
except KeyError:
    print("ok   unknown key -> KeyError")
try:
    v.derivation("k", True)
except TypeError:
    print("ok   bool version -> TypeError")
# seal accepts bytes-like, rejects others
v.seal("k2", bytearray(b"a")); v.seal("k2", memoryview(b"b"))
try:
    v.seal("k2", "x")
except TypeError:
    print("ok   seal non-bytes-like -> TypeError")
print("versions k2:", v.versions("k2"), "load:", v.load("k2",1), v.load("k2",2))
EOF

